INSERT INTO notifications(notification_id,user_id,source,type,subscription_id,title,body,payload_json,created_at,read) VALUES ('ntf_wh_b096e6b0','usr_wheelchair_009','route_watch','policy_update',NULL,'Metro transfer announcement | status change','The Message Center received a subway transfer announcement. The newly added fact is “temporary arrangements have been made for the transfer passage”; the follow-up requirement related to the subway transfer announcement is “refresh the route information before departure.”','{"topic": "Subway transfer", "action": "announcement", "priority": "high"}','2026-06-13T12:04:00Z',0);
INSERT INTO notifications(notification_id,user_id,source,type,subscription_id,title,body,payload_json,created_at,read) VALUES ('ntf_wh_b90c5f37','usr_wheelchair_009','listing_watch','status_update','sub_rent_status','Property-Viewing Materials Notice | Campus Services','The property-viewing materials notice differs from the previous record: the agent has added photos or measurement records. If this matter affects mobility or renting, it must be reverified together with “material completeness needs review.”','{"topic": "Property viewing materials", "action": "Announcement", "priority": "normal"}','2026-07-09T09:38:00Z',0);
INSERT INTO notifications(notification_id,user_id,source,type,subscription_id,title,body,payload_json,created_at,read) VALUES ('ntf_wh_d3b696f0','usr_wheelchair_009','student_service','keyword',NULL,'Assistive-Device Maintenance Notice | This Week''s Schedule','The assistive-device maintenance notice shows: maintenance appointment status updated. Before processing the assistive-device maintenance notice, also note that the inspection items and pickup and drop-off times are listed.','{"topic": "Assistive Equipment Maintenance", "action": "Announcement", "priority": "normal"}','2026-06-08T12:49:00Z',0);
INSERT INTO notifications(notification_id,user_id,source,type,subscription_id,title,body,payload_json,created_at,read) VALUES ('ntf_wh_69ff80f0','usr_wheelchair_009','student_service','keyword',NULL,'Book Due Date Announcement｜Today''s Matters','Regarding the book-due announcement, the system first alerts you that the borrowing period is approaching its end, then adds that the online renewal portal is still available. Shen Wenxi may decide whether to view the details based on their current plans.','{"topic": "Library Book Due Dates", "action": "Announcement", "priority": "normal"}','2026-07-02T15:38:00Z',0);
